import{_ as a,c as t,o as r,af as n}from"./chunks/framework.CpuDhtGM.js";const b=JSON.parse('{"title":"投资回报率","description":"","frontmatter":{},"headers":[],"relativePath":"value-investing/value-investing/return-on-investment.md","filePath":"value-investing/value-investing/return-on-investment.md","lastUpdated":1765801662000}'),i={name:"value-investing/value-investing/return-on-investment.md"};function s(o,e,l,p,d,u){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="投资回报率" tabindex="-1">投资回报率 <a class="header-anchor" href="#投资回报率" aria-label="Permalink to &quot;投资回报率&quot;">​</a></h1><h2 id="回报率" tabindex="-1">回报率 <a class="header-anchor" href="#回报率" aria-label="Permalink to &quot;回报率&quot;">​</a></h2><p>傲雪：</p><p>巴菲特的浮存金杠杆：<br> 巴菲特有 1700 多亿的浮存金。<br> 这些资金的成本几乎是 0，甚至是负的（保险本身还能赚不少钱）。<br> 这是巴菲特用全资的保险子公司搭建的特殊结构，普通人参照不了。</p><p>实际上，发现巴菲特基本在有 8%收益率的时候，就开始行动了。<br> 机会好的时候能买到 10%左右的收益率，再高的其实貌似就极少了。</p><p>所以重新理解把成本 3%的资金持续投入到收益率有 13%回报率的资产上。<br> 本质上，还是老巴有浮存金作为杠杆资金才能达到的的结果。<br> 有一个研究团队分析了伯克希尔 1976-2017 的年数据，计算出巴菲特使用的平均杠杆大约是 1.6-1.7：1。<br> 也就是 65%左右的杠杆。<br> 100 亿投资款，回报率 8%，回报金额 8 亿；<br> 加上 65 亿浮存金杠杆，回报率也是 8%，汇报金额 5.2 亿；<br> 8 亿+5.2 亿=13.2 亿；<br> 相对于 100 亿的自有本金投资款，在 8%的回报率下，确实会有 13.2%的回报率，在 13%以上了。<br> 何况浮存金也在越滚越大。</p><p>我们对标的目标，非折现情况下的 10%投资收益率，也就是通俗意义上的“十年回本”。<br> 在折现率设为 4%之后，基本上的情况下，都对应 8.3%左右的复利收益率。</p><p>其实这个要求已经比较高了。8%的收益率，差不多也就在击球区边缘的位置。<br> 要重新考虑下特价区的设置，可能对于不能上杠杆的我们来说，这个要求有点太高了。</p><h2 id="机会成本" tabindex="-1">机会成本 <a class="header-anchor" href="#机会成本" aria-label="Permalink to &quot;机会成本&quot;">​</a></h2><p>**对机会成本的衡量，要考虑“未来的机会成本”​，保留一定的前瞻性，而不是仅仅考虑眼前的机会成本。**巴菲特在 2003 年股东会上说：​“我们有 160 亿美元资产税前收益率只有 1.25%，每年利息为 2 亿美元。我们很容易就能买到 20 年到期的政府债券，并获得大约 5%的收益，我们可以获得每年 8 亿美元的收入。我们现在决定持有 2 亿美元收益的流动性资产，是因为相信不久的将来能找到 10%或回报更高的资产。如果我们选择投资 8 亿美元收益的债券，一年后要是出现大机会，我们损失就大了。​”巴菲特猜测他在未来适当时候会有机会以有吸引力的回报率投放资金，因此他不会浪费太多的“火力”现在就去购买较低回报、流动性差的资产，但这依然是基于机会成本的计算，因为这种暂时保留“火力”的做法大概率地在整体上最小化了机会成本。</p>',10)])])}const c=a(i,[["render",s]]);export{b as __pageData,c as default};
